#!/usr/bin/env node
// Generates tokens.css (open-design-agent-kit token contract) from colors_and_type.css.
//   node scripts/build-tokens.mjs           write tokens.css
//   node scripts/build-tokens.mjs --check   exit 1 if tokens.css is missing or stale
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { fileURLToPath } from "node:url";

const SOURCE_PATH = fileURLToPath(new URL("../colors_and_type.css", import.meta.url));
const OUTPUT_PATH = fileURLToPath(new URL("../tokens.css", import.meta.url));

const HEADER =
  "/* GENERATED by scripts/build-tokens.mjs from colors_and_type.css — do not edit */";
const ADDITIONS_MARKER =
  "/* ---- Open Design kit contract additions (DERIVED aliases — see docs/open-design-agent-kit.md) ---- */";

// Vendored from open-design-agent-kit packages/core/src/vendored/designTokenSchema.ts (TOKEN_SCHEMA).
export const KIT_TOKENS = Object.freeze([
  "--bg", "--surface", "--surface-warm", "--fg", "--fg-2", "--muted", "--meta",
  "--border", "--border-soft", "--accent", "--accent-on", "--accent-hover",
  "--accent-active", "--success", "--warn", "--danger",
  "--font-display", "--font-body", "--font-mono",
  "--text-xs", "--text-sm", "--text-base", "--text-lg", "--text-xl", "--text-2xl",
  "--text-3xl", "--text-4xl", "--leading-body", "--leading-tight", "--tracking-display",
  "--space-1", "--space-2", "--space-3", "--space-4", "--space-5", "--space-6",
  "--space-8", "--space-12",
  "--section-y-desktop", "--section-y-tablet", "--section-y-phone",
  "--radius-sm", "--radius-md", "--radius-lg", "--radius-pill",
  "--elev-flat", "--elev-ring", "--elev-raised", "--focus-ring",
  "--motion-fast", "--motion-base", "--ease-standard",
  "--container-max", "--container-gutter-desktop", "--container-gutter-tablet",
  "--container-gutter-phone",
]);

// Kit-contract tokens the source does not declare. See docs/open-design-agent-kit.md.
export const CONTRACT_ADDITIONS = Object.freeze({
  "--surface-warm": "var(--surface)",
  "--fg-2": "var(--fg)",
  "--meta": "var(--muted)",
  "--border-soft": "var(--border-subtle)",
  "--accent-on": "var(--accent-contrast)",
  "--accent-hover": "color-mix(in oklab, var(--accent), black 8%)",
  "--accent-active": "color-mix(in oklab, var(--accent), black 14%)",
  "--success": "var(--status-success)",
  "--warn": "var(--status-warning)",
  "--danger": "var(--status-danger)",
  "--font-mono":
    'ui-monospace, "SF Mono", "JetBrains Mono", Menlo, Monaco, Consolas, monospace',
  "--leading-body": "1.5",
  "--leading-tight": "1.1",
  "--tracking-display": "0",
  "--space-5": "20px",
  "--radius-lg": "var(--radius-md)",
  "--elev-flat": "none",
  "--elev-ring": "0 0 0 1px var(--border)",
  "--elev-raised": "var(--shadow-sm)",
  "--motion-fast": "var(--duration-fast)",
  "--motion-base": "var(--duration-base)",
  "--section-y-desktop": "var(--section-py-lg)",
  "--section-y-tablet": "var(--section-py)",
  "--section-y-phone": "var(--section-py)",
  "--container-gutter-desktop": "var(--container-pad-lg)",
  "--container-gutter-tablet": "var(--container-pad)",
  "--container-gutter-phone": "var(--container-pad)",
});

// The kit applies --focus-ring as a box-shadow; the source uses it as an outline color.
export const FOCUS_RING_OVERRIDE = "0 0 0 2px var(--bg), 0 0 0 4px var(--color-brand-blue)";

const stripComments = (css) => css.replace(/\/\*[\s\S]*?\*\//g, "");

/** Declarations of the first top-level `:root` block, comments stripped, in source order. */
export function parseRootDeclarations(css) {
  const src = stripComments(css);
  let depth = 0;
  let bodyStart = -1;
  for (let i = 0; i < src.length; i++) {
    const ch = src[i];
    if (ch === "{") {
      if (depth === 0 && /(^|[\s;}]):root\s*$/.test(src.slice(0, i))) {
        bodyStart = i + 1;
        break;
      }
      depth++;
    } else if (ch === "}") {
      depth--;
    }
  }
  if (bodyStart < 0) throw new Error("No top-level :root block found");

  const decls = [];
  let parens = 0;
  let quote = null;
  let start = bodyStart;
  for (let i = bodyStart; i < src.length; i++) {
    const ch = src[i];
    if (quote) {
      if (ch === quote) quote = null;
      continue;
    }
    if (ch === '"' || ch === "'") quote = ch;
    else if (ch === "(") parens++;
    else if (ch === ")") parens--;
    else if (parens === 0 && (ch === ";" || ch === "}")) {
      const chunk = src.slice(start, i).trim();
      if (chunk) {
        const colon = chunk.indexOf(":");
        if (colon < 0) throw new Error(`Malformed declaration in :root: ${chunk}`);
        decls.push({ name: chunk.slice(0, colon).trim(), value: chunk.slice(colon + 1).trim() });
      }
      if (ch === "}") return decls;
      start = i + 1;
    }
  }
  throw new Error("Unterminated :root block");
}

/** Full tokens.css text for the given colors_and_type.css source. */
export function buildTokensCss(sourceCss) {
  const decls = parseRootDeclarations(sourceCss);
  const declared = new Set(decls.map((d) => d.name));
  const clashes = Object.keys(CONTRACT_ADDITIONS).filter((n) => declared.has(n));
  if (clashes.length) {
    throw new Error(
      `colors_and_type.css already declares contract addition(s) ${clashes.join(", ")}; ` +
        "remove them from CONTRACT_ADDITIONS in scripts/build-tokens.mjs deliberately.",
    );
  }
  const line = (name, value) => `  ${name}: ${value};`;
  const lines = decls.map(({ name, value }) =>
    line(name, name === "--focus-ring" ? FOCUS_RING_OVERRIDE : value),
  );
  if (!declared.has("--focus-ring")) lines.push(line("--focus-ring", FOCUS_RING_OVERRIDE));
  return [
    HEADER,
    ":root {",
    ...lines,
    "",
    `  ${ADDITIONS_MARKER}`,
    ...Object.entries(CONTRACT_ADDITIONS).map(([n, v]) => line(n, v)),
    "}",
    "",
  ].join("\n");
}

/** Compare the current tokens.css text (undefined = missing) against a fresh build. */
export function checkTokens(sourceCss, currentTokensCss) {
  if (currentTokensCss === undefined) {
    return { ok: false, message: "tokens.css is missing — run `npm run build:tokens`." };
  }
  if (currentTokensCss !== buildTokensCss(sourceCss)) {
    return {
      ok: false,
      message: "tokens.css is out of date with colors_and_type.css — run `npm run build:tokens`.",
    };
  }
  return { ok: true, message: "tokens.css is up to date." };
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const source = readFileSync(SOURCE_PATH, "utf8");
  if (process.argv.includes("--check")) {
    const current = existsSync(OUTPUT_PATH) ? readFileSync(OUTPUT_PATH, "utf8") : undefined;
    const { ok, message } = checkTokens(source, current);
    (ok ? console.log : console.error)(message);
    process.exit(ok ? 0 : 1);
  }
  writeFileSync(OUTPUT_PATH, buildTokensCss(source));
  console.log("Wrote tokens.css");
}
